css='''*{box-sizing:border-box}html{min-height:100%;background:#0d0814}body{margin:0;min-height:100dvh;font:15px/1.6 "Pretendard Variable",Pretendard,-apple-system,"Apple SD Gothic Neo",sans-serif;color:#F7F4F0;background:linear-gradient(180deg,rgba(18,8,28,.35),rgba(18,8,28,.10) 42%,rgba(18,8,28,.72)),url(302-v4-background.webp) 42% 50%/cover fixed}button,input,select{font:inherit}a{color:inherit}button,a,input,select{touch-action:manipulation}button,a{cursor:pointer}header{max-width:720px;margin:auto;padding:20px 16px;display:grid;grid-template-columns:44px 1fr 44px;align-items:center;gap:12px}.back{display:grid;place-items:center;width:44px;height:44px;border:1px solid #ffffff24;border-radius:50%;background:#180c2494;color:white;text-decoration:none}.brand{justify-self:center;padding:9px 24px;background:#180c2494;border:1px solid #ffffff24;border-radius:999px;display:flex;align-items:center;gap:10px;font-size:13px;letter-spacing:1px;font-weight:600}.brand img{width:24px;filter:brightness(0) invert(1)}main{max-width:488px;margin:18px auto 32px;padding:0 16px}.sheet{background:rgba(24,12,36,.78);border:1px solid rgba(255,255,255,.14);border-radius:24px;padding:28px 24px}.eyebrow{font-size:12px;color:#D2AEFC;letter-spacing:.08em;font-weight:600;margin-bottom:10px}h1{font-size:24px;font-weight:600;line-height:1.5;letter-spacing:-.03em;margin:0 0 12px}h2{font-size:18px;font-weight:600;margin:0 0 12px}p{color:#CFC6D6;margin:0 0 24px;font-size:15px}.hint{font-size:13px;color:#CFC6D6;margin:12px 0 0}.field{display:block;font-size:13px;color:#CFC6D6;margin-top:20px}.field span{color:#D2AEFC;margin-left:6px}input:not([type=checkbox]),select{display:block;width:100%;height:48px;background:rgba(24,12,36,.58);border:1px solid #a89aaf;border-radius:12px;color:#F7F4F0;margin-top:8px;padding:0 14px;outline:none}input::placeholder{color:#b9adc4}option{background:#180c24}.button,button{min-height:48px;width:100%;padding:12px 20px;border:1px solid #ffffff36;border-radius:999px;background:rgba(24,12,36,.58);color:#F7F4F0;display:flex;align-items:center;justify-content:center;text-decoration:none;font-size:15px;font-weight:600;line-height:22px;margin-top:12px}.primary{background:#D2AEFC;color:#241332;border-color:#D2AEFC}.subtle{background:transparent;border-color:#ffffff36}.actions{margin-top:24px;display:grid;gap:0}.divider{display:flex;align-items:center;gap:16px;margin:24px 0;color:#CFC6D6;font-size:12px}.divider:before,.divider:after{content:"";height:1px;background:#ffffff24;flex:1}.checks{margin:20px 0}.check{display:flex;gap:12px;align-items:flex-start;font-size:13px;color:#F7F4F0;padding:10px 0}.check input{width:20px;height:20px;flex:none;margin:1px 0;accent-color:#D2AEFC}.check a{margin-left:auto;color:#D2AEFC;white-space:nowrap}.tag{font-size:12px;border-radius:999px;background:#ffffff14;border:1px solid #ffffff24;padding:4px 10px;color:#D2AEFC;display:inline-block;margin-bottom:16px}.notice{padding:16px;background:rgba(24,12,36,.58);border:1px solid #ffffff24;border-radius:16px;margin:20px 0}.notice p{margin:0;font-size:13px}.row{display:flex;gap:12px;align-items:center;justify-content:space-between}.row .button{width:auto}.muted{color:#CFC6D6;font-size:13px}.foot{text-align:center;font-size:12px;margin:24px 0 0;color:#F7F4F0;text-shadow:0 1px 4px #180c24}.foot a{display:inline-block;padding:10px}details{font-size:13px;color:#CFC6D6;margin:18px 0}details p{font-size:13px;margin-top:12px}summary{cursor:pointer}.status{color:#E8B4A0;font-size:13px;margin-top:16px}:focus-visible{outline:2px solid #D2AEFC;outline-offset:3px}@media(min-width:768px){header{padding:32px}main{margin:32px auto;max-width:520px;padding:0 24px}.sheet{padding:32px}.button,button{min-height:48px}}'''
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>회원가입 · 클래스 스타일 v4</title><link rel="stylesheet" href="302-v4.css"><header><a class="back" href="?screen=start" aria-label="가입 시작으로">‹</a><div class="brand"><img src="302-v4-logo.svg" alt="">MIND BREEZE</div></header><main><section class="sheet" id="screen"></section><div class="foot">가입 흐름 시안 · v4<br><a href="302-v4-board.html">전체 화면 보기</a></div></main><script>
const params=new URLSearchParams(location.search);let screen=params.get('screen')||'start';
const link=(label,to,cls='')=>`<a class="button ${cls}" href="?screen=${to}">${label}</a>`;
const field=(label,placeholder,type='text',required=true)=>`<label class="field">${label}<input type="${type}" placeholder="${placeholder}" ${required?'required':''}></label>`;
const title=(step,t,desc)=>`<div class="eyebrow">${step}</div><h1>${t}</h1><p>${desc}</p>`;
const gender=`<label class="field">성별 <span>필수</span><select name="gender" required><option value="">선택해 주세요</option><option value="female">여성</option><option value="male">남성</option><option value="other">기타</option></select></label>`;
const checks=`<div class="checks">${['이용약관','개인정보 처리','민감정보 처리'].map(t=>`<label class="check"><input type="checkbox" required><span>[필수] ${t} 동의</span><a href="#terms">보기</a></label>`).join('')}<details><summary>선택 동의 항목</summary><label class="check"><input type="checkbox">뇌파 측정 동의</label><label class="check"><input type="checkbox">연구 활용 동의</label></details></div>`;
const terms=`<details id="terms"><summary>동의 전문 확인</summary><p>실제 화면에서는 선택한 약관의 전문을 엽니다. 이 시안은 동의 기록을 저장하지 않습니다.</p></details>`;
let views={
start:title('회원 가입','나를 위한 시간,<br>여기서 시작해요','사용할 계정을 선택해 주세요.')+link('<img src="302-v4-google.svg" width="20" height="20" alt="" aria-hidden="true">Google로 계속하기','social','social-google')+link('<img src="302-v4-apple.svg" width="18" height="18" alt="" aria-hidden="true">Apple로 계속하기','social','social-apple')+'<p class="hint">Apple은 iOS 앱에서 이용할 수 있어요.</p><div class="divider">또는</div>'+link('이메일로 가입하기','email','primary')+'<div class="foot">이미 계정이 있나요? <a href="?screen=login">로그인</a></div>',
login:title('로그인','다시 만나 반가워요','가입한 계정으로 이어서 이용해 주세요.')+'<form data-next="home">'+field('이메일','이메일 주소','email')+field('비밀번호','비밀번호','password')+'<div class="actions"><button class="primary">로그인</button></div></form><p class="hint">입력값은 시안에서 전송하거나 저장하지 않아요.</p>',
email:title('이메일 가입 · 1 / 2','이메일을 확인할게요','인증번호를 받을 이메일을 입력해 주세요.')+'<form id="email-form">'+field('이메일','member@example.test','email')+'<button class="primary">인증번호 받기</button></form><div id="otp" hidden><form data-next="info">'+field('인증번호','6자리 숫자','text')+'<p class="hint">시안 확인용 번호는 123456이에요.<br>실제 메일은 발송되지 않아요.</p><button class="primary">인증하고 다음으로</button></form></div>',
info:title('이메일 가입 · 2 / 2','가입 정보를 확인해요','성별을 포함한 가입 정보를 입력해 주세요. 전화번호는 나중에 추가할 수 있어요.')+'<form data-next="home">'+field('이름','이름을 입력해 주세요')+gender+field('생년월일','YYYY.MM.DD')+field('비밀번호','영문·숫자·특수문자 8자 이상','password')+field('비밀번호 확인','비밀번호를 다시 입력해 주세요','password')+(params.has('invite')?'<div class="notice"><b>초대받은 코치와 연결해요</b><p>마음숲 코치 · 예시 초대</p></div>':field('코치 코드','초대받은 6자리 코드'))+checks+'<button class="primary">동의하고 가입하기</button></form>'+terms,
social:title('소셜 가입 · 정보 확인','거의 다 왔어요','계정에서 가져온 정보와 동의 항목을 확인해 주세요.')+'<span class="tag">소셜 계정 인증 후</span><form data-next="home">'+field('이름','소셜 계정의 이름').replace('<input ', '<input value="예시 회원" ')+gender+field('생년월일','YYYY.MM.DD')+'<p class="hint">가입 연령 확인에 사용해요. 이미 입력한 생년월일은 다시 묻지 않아요.</p>'+checks+'<button class="primary">동의하고 가입하기</button></form>'+terms,
profile:title('선택 프로필','지금 입력하지 않아도 돼요','원할 때 설정에서 추가해 주세요.')+'<form data-next="saved">'+field('전화번호 · 선택','010-0000-0000','tel',false)+'<div class="notice"><p>나중에 하기를 누르면<br>다음 로그인부터 다시 묻지 않아요.</p></div><div class="actions"><button class="primary">입력한 정보 저장</button>'+link('나중에 하기','later','subtle')+'</div></form>',
home:title('회원 홈','오늘도 나의 속도로','내 클래스에서 함께해요.')+'<div class="notice"><div class="row"><b>마음 살피기 클래스</b><span class="tag">예시</span></div><p>11월 11일 · 14:00</p>'+link('클래스 보기','class','primary')+'</div>'+link('설정에서 프로필 관리','settings','subtle'),
later:title('회원 홈','바로 이용하셔도 돼요','프로필은 설정에서 언제든 입력할 수 있어요.')+'<div class="notice" role="status"><p>프로필 입력 안내를 다시 표시하지 않아요.<br>다른 기기에서도 같은 선택을 유지해요.</p></div>'+link('내 클래스 보기','home','primary')+link('설정으로','settings','subtle'),
saved:title('프로필','입력한 정보를 저장했어요','수정이 필요하면 설정에서 변경해 주세요.')+link('홈으로','home','primary'),
settings:title('설정 / 내 정보','프로필 관리','필요한 정보만 편하게 추가해 주세요.')+'<div class="notice"><b>선택 프로필</b><p>전화번호</p>'+link('프로필 입력하기','profile')+'</div><p class="hint">로그인할 때 자동으로 입력을 요청하지 않아요.</p>'+link('홈으로','home','primary'),
'class':title('클래스','마음 살피기 클래스','예시 클래스 · 11월 11일 14:00')+'<div class="notice"><p>가입 흐름을 확인하는 시안이에요.<br>실제 클래스에는 접속하지 않아요.</p></div>'+link('내 홈으로','home','primary'),
error:title('프로필','선택을 저장하지 못했어요','연결을 확인한 뒤 다시 시도해 주세요.')+'<div class="notice"><p>다른 기기에는 아직 반영되지 않았어요.</p></div>'+link('다시 시도하기','profile','primary')+link('이번에는 홈으로','home','subtle')};
document.getElementById('screen').innerHTML=views[screen]||views.start;
document.querySelectorAll('form[data-next]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();if(screen==='email'&&f.querySelector('input').value!=='123456'){let n=f.querySelector('.status');if(!n){n=document.createElement('p');n.className='status';n.setAttribute('role','alert');f.append(n)}n.textContent='인증번호를 다시 확인해 주세요.';return}location.href='?screen='+f.dataset.next+(params.has('invite')?'&invite=example':'')}));
document.getElementById('email-form')?.addEventListener('submit',e=>{e.preventDefault();document.getElementById('otp').hidden=false;document.querySelector('#otp input').focus()});
</script></html>'''
css+='\n.button.social-google,.button.social-apple{height:52px;gap:12px;padding:0 16px}.button.social-google{background:#fff;color:#5F0080;border-color:rgba(255,255,255,.3)}.button.social-apple{background:#000;color:#fff;border-color:#000}.social-apple img{filter:brightness(0) invert(1)}.social-google img,.social-apple img{flex:none;object-fit:contain}\n'
(p/'302-v4.css').write_text(css);(p/'302-v4.html').write_text(html)
board='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SDD-302 · 클래스 스타일 v4</title><style>*{box-sizing:border-box}body{margin:0;background:#100a18;color:#F7F4F0;font:15px/1.6 -apple-system,"Apple SD Gothic Neo",sans-serif}header{padding:32px;max-width:1280px;margin:auto}h1{font-size:28px;font-weight:600;margin:8px 0}p{color:#CFC6D6}a{color:#D2AEFC}nav{display:flex;gap:16px;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(350px,1fr));gap:32px;padding:0 32px 40px;max-width:1340px;margin:auto}section{min-width:0}iframe{width:100%;height:870px;border:1px solid #ffffff24;border-radius:24px;background:#180c24}h2{font-size:15px;font-weight:500}@media(max-width:500px){header{padding:24px 16px}.grid{display:block;padding:0 0 24px}.grid h2{padding:0 16px}iframe{border-radius:0;height:920px}}.badge{color:#D2AEFC;font-size:12px;letter-spacing:2px}</style><header><div class="badge">MIND BREEZE / SDD-302 / V4</div><h1>클래스에서 느꼈던 분위기 그대로</h1><p>이전 클래스의 자연 배경과 어두운 반투명 패널을 가입 화면으로 이어갑니다.<br>가입 후 바로 홈으로. 선택 프로필은 나중에 하고, 다시 묻지 않습니다.</p><nav><a href="302-v4.html">가입 흐름 직접 열기</a><a href="302-v4.html?screen=profile">선택 프로필</a><a href="302-v4.html?screen=later">나중에 하기 이후</a><a href="http://100.105.138.107:8001/design-1105/302-index.html">이전 밝은 시안</a></nav></header><div class="grid">'''
for key,title in [('start','01 · 가입 시작'),('social','02 · 소셜 정보 확인'),('email','03 · 이메일 인증'),('info','04 · 이메일 가입 정보'),('profile','05 · 선택 프로필'),('later','06 · 다시 묻지 않는 홈')]:board+=f'<section><h2>{title}</h2><iframe title="{title}" src="302-v4.html?screen={key}" loading="lazy"></iframe></section>'
(p/'302-v4-board.html').write_text(board+'</div></html>')
print('v4 생성')
